1	# Crush CLI (charmbracelet) configuration with OpenAI Codex models and MCP.
2	#
3	# Crush reads config from $HOME/.config/crush/crush.json (or .crush.json in
4	# the project). We override the built-in `openai` provider to register the
5	# latest Codex model IDs and default the large/small slots to them.
6	#
7	# OPENAI_API_KEY must be exported in the shell that runs `crush`.
8	{
9	  config,
10	  pkgs,
11	  lib,
12	  ...
13	}:
14	let
15	  cfg = config.programs.mcp;
16	
17	  # MCP servers for Crush. Import shared definitions and ensure `type` is specified.
18	  # Crush requires `type = "stdio"` for command-based servers.
19	  mcpServers =
20	    let
21	      servers =
22	        (import ../mcp/servers.nix {
23	          inherit
24	            pkgs
25	            lib
26	            cfg
27	            config
28	            ;
29	        }).mcpServers;
30	    in
31	    lib.mapAttrs (
32	      _name: value: if (value ? command && !(value ? type)) then value // { type = "stdio"; } else value
33	    ) servers;
34	
35	  # Latest Codex-family models as of 2026-04. gpt-5.1-codex is the current
36	  # API-available Codex model; gpt-5.1 is the general-purpose counterpart
37	  # used as the "small" slot for lighter tasks.
38	  openaiModels = [
39	    {
40	      id = "gpt-5.1-codex";
41	      name = "GPT-5.1 Codex";
42	      context_window = 400000;
43	      default_max_tokens = 128000;
44	      can_reason = true;
45	      has_reasoning_efforts = true;
46	      default_reasoning_effort = "medium";
47	      supports_attachments = true;
48	    }
49	    {
50	      id = "gpt-5.1";
51	      name = "GPT-5.1";
52	      context_window = 400000;
53	      default_max_tokens = 128000;
54	      can_reason = true;
55	      has_reasoning_efforts = true;
56	      default_reasoning_effort = "medium";
57	      supports_attachments = true;
58	    }
59	  ];
60	
61	  mucieModels = [
62	    {
63	      id = "gemma-4-26b-a4b-it-4bit";
64	      name = "gemma4:e4b (omlx @mucie)";
65	    }
66	  ];
67	
68	  # Self-hosted Ollama instance. Uses Ollama's OpenAI-compatible endpoint
69	  # so we declare provider type "openai" with a custom base_url.
70	  # context_window is set to 65536 which requires Ollama to run with
71	  # `num_ctx >= 65536`. On lucie KV cache is quantized to q8_0 and flash
72	  # attention is enabled (see hosts/lucie/default.nix), so a 64k cache
73	  # fits fully on the RTX 5090's 32 GB VRAM alongside the model weights.
74	  lucieModels = [
75	    {
76	      id = "gemma4:26b";
77	      name = "Gemma 4 26B (ollama @lucie)";
78	      context_window = 65536;
79	      default_max_tokens = 4096;
80	    }
81	    {
82	      id = "qwen3.6:27b";
83	      name = "Qwen 3.6 (ollama @lucie)";
84	      context_window = 65536;
85	      default_max_tokens = 4096;
86	    }
87	  ];
88	
89	  crushConfig = {
90	    "$schema" = "https://charm.land/crush.json";
91	    providers = {
92	      openai = {
93	        type = "openai";
94	        api_key = "$OPENAI_API_KEY";
95	        models = openaiModels;
96	      };
97	      lucie = {
98	        type = "openai";
99	        base_url = "http://10.100.0.100:11434/v1";
100	        api_key = "ollama";
101	        models = lucieModels;
102	      };
103	      mucie = {
104	        type = "openai";
105	        base_url = "http://127.0.0.1:8000/v1";
106	        api_key = "asdfasdf";
107	        models = mucieModels;
108	      };
109	    };
110	    models = {
111	      large = {
112	        model = "gpt-5.1-codex";
113	        provider = "openai";
114	      };
115	      small = {
116	        model = "gpt-5.1";
117	        provider = "openai";
118	      };
119	    };
120	    mcp = mcpServers;
121	    options = {
122	      tui = {
123	        # Start in compact layout (sidebar hidden). Toggle at runtime with
124	        # Ctrl+P -> "Toggle Sidebar" (visible only when terminal >= 120 cols).
125	        compact_mode = true;
126	      };
