input.new_string:
  # Self-hosted models served through the LiteLLM proxy on lucie
  # (hosts/lucie/litellm.nix, port 14000, reached over WireGuard at
  # 10.100.0.100). LiteLLM exposes an OpenAI-compatible API, so we declare a
  # custom provider using the `chat` wire protocol. The proxy requires the
  # LiteLLM master key: export it as LITELLM_API_KEY in the shell that runs
  # `codex`. Model IDs must match `model_name` entries in the LiteLLM config.
  litellmModels = {
    qwen-coder = "qwen3-coder:30b-a3b-q4_K_M";
    qwen-coder-next = "qwen3-coder-next:q4_K_M";
  };

  # One Codex profile per LiteLLM model, e.g. `codex --profile qwen-coder`.
  litellmProfiles = lib.mapAttrs (_name: model: {
    inherit model;
    model_provider = "litellm";
  }) litellmModels;

  tomlFormat = pkgs.formats.toml { };
in
{
  home.packages = [ pkgs.codex ];

  home.file.".codex/config.toml".source = tomlFormat.generate "codex-config.toml" {
    mcp_servers = mcpServers;

    model_providers.litellm = {
      name = "LiteLLM (lucie)";
      base_url = "http://10.100.0.100:14000/v1";
      env_key = "LITELLM_API_KEY";
      wire_api = "chat";
    };

    profiles = litellmProfiles;
  };
}

