input.new_string:
  tomlFormat = pkgs.formats.toml { };

  # Codex persists runtime state (notably per-directory trust decisions) back
  # into config.toml, so it cannot be a read-only Nix store symlink — writes
  # fail with "failed to persist config". Generate the file in the store and
  # install a writable copy via an activation script instead. It is
  # force-refreshed on every switch, which also keeps the MCP server store
  # paths current; the trade-off is that trust entries Codex records at runtime
  # for directories not pre-declared below are reset on the next switch.
  codexConfig = tomlFormat.generate "codex-config.toml" {
    mcp_servers = mcpServers;

    model_providers.litellm = {
      name = "LiteLLM (lucie)";
      base_url = "http://10.100.0.100:14000/v1";
      env_key = "LITELLM_API_KEY";
      wire_api = "responses";
    };

    profiles = litellmProfiles;

    # Pre-trust this dotfiles repo so Codex does not prompt (and try to write)
    # on startup here. Add more project roots as needed.
    projects."${config.home.homeDirectory}/Projects/github.com/gotha/dotfiles".trust_level =
      "trusted";
  };
in
{
  home.packages = [ pkgs.codex ];

  home.activation.codexConfig = lib.hm.dag.entryAfter [ "writeBoundary" ] ''
    $DRY_RUN_CMD rm -f $VERBOSE_ARG "$HOME/.codex/config.toml"
    $DRY_RUN_CMD install $VERBOSE_ARG -Dm644 ${codexConfig} "$HOME/.codex/config.toml"
  '';
}

